/* Presentation layer only. Existing catalog, histories and test selection remain canonical. */
(()=>{
 const root=document.getElementById('reading-home'),grid=root?.querySelector('.grid'),dialog=document.getElementById('book-detail');if(!grid||!dialog)return;
 const colors=['#3e4d3b','#3b284a','#85472f','#263d50','#68614b','#3b5255'];let opener;
 function close(){dialog.close()}
 dialog.querySelector('.book-detail-close').onclick=close;dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()});
 function open(card){opener=card.querySelector('.book-hit');const body=dialog.querySelector('.book-detail-content');body.replaceChildren();const picture=card.querySelector('.cover').cloneNode(true);picture.className='detail-picture';const info=document.createElement('div');info.className='detail-info';for(const selector of ['.label','h3','.meta','.state','.open-lesson']){const old=card.querySelector(selector);if(!old)continue;const node=old.cloneNode(true);node.removeAttribute('id');if(selector==='h3')node.id='book-detail-title';info.append(node)}const credit=card.querySelector('.book-front>small');if(credit){const c=credit.cloneNode(true);c.removeAttribute('style');c.className='photo-credit';info.append(c)}body.append(picture,info);dialog.showModal()}
 function enhance(){[...grid.querySelectorAll('article')].forEach((card,i)=>{if(card.dataset.bookshelf)return;card.dataset.bookshelf='true';card.style.setProperty('--book-color',colors[i%colors.length]);const title=card.querySelector('h3')?.textContent||'';const front=document.createElement('div');front.className='book-front';while(card.firstChild)front.append(card.firstChild);const spine=document.createElement('div');spine.className='book-spine';spine.setAttribute('aria-hidden','true');const text=document.createElement('span');text.textContent=title;spine.append(text);const top=document.createElement('div');top.className='book-top';top.setAttribute('aria-hidden','true');const edge=document.createElement('div');edge.className='book-edge';edge.setAttribute('aria-hidden','true');const hit=document.createElement('button');hit.type='button';hit.className='book-hit';hit.setAttribute('aria-label','Xem bài '+title);hit.onclick=()=>open(card);const volume=document.createElement("div");volume.className="book-volume";volume.append(spine,top,edge,front,hit);card.append(volume);});updateCount()}
 function updateCount(){const cards=[...grid.querySelectorAll('article')],visible=cards.filter(c=>!c.hidden);document.getElementById('shelf-count').textContent=visible.length+' bài đọc';/* Rows carry individual shelf segments, so filtering leaves no empty shelves. */}
 const observer=new MutationObserver(enhance);observer.observe(grid,{childList:true});const filterObserver=new MutationObserver(updateCount);filterObserver.observe(grid,{attributes:true,subtree:true,attributeFilter:['hidden']});enhance();
})();
